INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('5', '4', 'Super Admin', 'update', 'App\\Models\\CompanyInfo', '1', 'Mengubah Info Perusahaan: PT. Bank Perekonomian Rakyat Syariah Bangka Belitung', '{\"mission\": \"1. Menggerakkan pemberdayaan ekonomi rakyat dalam rangka turut serta berperan menuju masyarakat Provinsi Kepulauan Bangka Belitung yang maju, mandiri dan sejahtera.\\n2. Menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha.\\n3. Meningkatkan kualitas pelayanan di seluruh kantor.\\n4. Meningkatkan kuantitas dan kualitas sumber daya insani menuju tenaga kerja yang profesional.\\n5. Meningkatkan kerja sama dan bersinergi dengan pihak lain.\", \"lps_tagline\": \"Bank merupakan peserta penjaminan LPS\"}', '{\"mission\": \"1. Menggerakkan pemberdayaan ekonomi rakyat dalam rangka turut serta berperan menuju masyarakat Provinsi Kepulauan Bangka Belitung yang maju, mandiri dan sejahtera. 2. Menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha. 3. Meningkatkan kualitas pelayanan di seluruh kantor. 4. Meningkatkan kuantitas dan kualitas sumber daya insani menuju tenaga kerja yang profesional. 5. Meningkatkan kerja sama dan bersinergi dengan pihak lain.\", \"lps_tagline\": \"Bank merupakan peserta penjaminan LPS | Maksimum nilai simpanan yang dijamin LPS per Nasabah per Bank adalah Rp. 2 Miliar\"}', '10.10.10.37', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36 Edg/144.0.0.0', 'http://10.10.10.37:8000/admin/company-info', 'PUT', '2025-12-31 15:18:02', '2025-12-31 15:18:02');
