INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('58', '10', 'Muhammad Fadly', 'update', 'App\\Models\\News', '1', 'Mengubah Berita: Rapat Umum Pemegang Saham Luar Biasa (RUPS-LB) BPRS Bangka Belitung 2024', '{\"slug\": \"bpr-syariah-raih-penghargaan-bank-terbaik-2024\", \"title\": \"BPR Syariah Raih Penghargaan Bank Terbaik 2024\", \"content\": \"<p>Bank Perekonomian Rakyat Syariah dengan bangga mengumumkan pencapaian penghargaan sebagai \\\"Bank Syariah Terbaik 2024\\\" dalam kategori BPR Syariah dari Asosiasi Bank Syariah Indonesia.</p>\\n\\n<p>Penghargaan ini diberikan berdasarkan penilaian komprehensif terhadap kinerja keuangan, inovasi produk, pelayanan nasabah, dan kontribusi terhadap pengembangan ekonomi syariah di Indonesia.</p>\\n\\n<p>\\\"Penghargaan ini merupakan hasil kerja keras seluruh tim dan kepercayaan nasabah yang telah mempercayakan kebutuhan keuangan syariah mereka kepada kami,\\\" ujar Direktur Utama BPR Syariah.</p>\\n\\n<p>Sepanjang tahun 2024, BPR Syariah telah meluncurkan berbagai inovasi produk dan layanan, termasuk digitalisasi layanan perbankan dan ekspansi jaringan kas keliling untuk menjangkau masyarakat di daerah terpencil.</p>\", \"category\": \"Berita\", \"published_at\": \"2025-12-26T08:16:18.000000Z\"}', '{\"slug\": \"rapat-umum-pemegang-saham-luar-biasa-rups-lb-bprs-bangka-belitung-2024\", \"title\": \"Rapat Umum Pemegang Saham Luar Biasa (RUPS-LB) BPRS Bangka Belitung 2024\", \"content\": \"<p><strong>Pangkalpinang </strong>–&nbsp; BPRS Bangka Belitung telah di adakan Rapat Umum Pemegang Saham Luar Biasa Tahun 2024</p>\", \"category\": \"berita\", \"published_at\": \"2025-12-26 15:16:00\"}', '10.10.10.28', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 'http://10.10.10.37:8000/admin/news/1', 'PUT', '2025-12-31 16:17:43', '2025-12-31 16:17:43');
