INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('63', '10', 'Muhammad Fadly', 'delete', 'App\\Models\\News', '2', 'Menghapus Berita: Peluncuran Produk Pembiayaan Mikro Syariah untuk UMKM', '{\"id\": 2, \"slug\": \"peluncuran-produk-pembiayaan-mikro-syariah-untuk-umkm\", \"title\": \"Peluncuran Produk Pembiayaan Mikro Syariah untuk UMKM\", \"author\": \"Divisi Produk & Marketing\", \"content\": \"<p>Dalam rangka mendukung pertumbuhan Usaha Mikro, Kecil, dan Menengah (UMKM), BPR Syariah meluncurkan produk pembiayaan mikro syariah dengan skema yang lebih fleksibel dan mudah diakses.</p>\\n\\n<p>Produk ini dirancang khusus untuk memenuhi kebutuhan modal kerja UMKM dengan proses yang cepat dan persyaratan yang tidak memberatkan. Pembiayaan tersedia mulai dari Rp 5 juta hingga Rp 200 juta dengan jangka waktu hingga 3 tahun.</p>\\n\\n<p>Keunggulan produk ini antara lain:</p>\\n<ul>\\n<li>Proses persetujuan maksimal 3 hari kerja</li>\\n<li>Margin yang kompetitif</li>\\n<li>Tanpa denda keterlambatan</li>\\n<li>Pendampingan usaha dari tim ahli</li>\\n</ul>\\n\\n<p>Untuk informasi lebih lanjut, UMKM dapat mengunjungi kantor cabang terdekat atau menghubungi layanan customer service kami.</p>\", \"excerpt\": \"BPR Syariah meluncurkan produk pembiayaan mikro syariah untuk mendukung pertumbuhan UMKM dengan skema yang fleksibel.\", \"category\": \"Berita\", \"author_id\": null, \"created_at\": \"2025-12-31 15:16:18\", \"updated_at\": \"2025-12-31 15:16:18\", \"is_published\": 1, \"published_at\": \"2025-12-21 15:16:18\", \"featured_image\": null}', NULL, '10.10.10.28', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 'http://10.10.10.37:8000/admin/news/2', 'DELETE', '2025-12-31 16:56:33', '2025-12-31 16:56:33');
INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('64', '10', 'Muhammad Fadly', 'delete', 'App\\Models\\News', '3', 'Menghapus Berita: Ekspansi Layanan Kas Keliling ke 5 Kecamatan Baru', '{\"id\": 3, \"slug\": \"ekspansi-layanan-kas-keliling-ke-5-kecamatan-baru\", \"title\": \"Ekspansi Layanan Kas Keliling ke 5 Kecamatan Baru\", \"author\": \"Divisi Operasional\", \"content\": \"<p>BPR Syariah terus berkomitmen untuk memberikan akses layanan perbankan syariah yang mudah dijangkau masyarakat. Sebagai wujud komitmen tersebut, kami memperluas jangkauan layanan kas keliling ke 5 kecamatan baru.</p>\\n\\n<p>Kecamatan yang menjadi target ekspansi meliputi:</p>\\n<ul>\\n<li>Kecamatan Cibinong, Bogor</li>\\n<li>Kecamatan Ciputat, Tangerang Selatan</li>\\n<li>Kecamatan Bekasi Utara, Bekasi</li>\\n<li>Kecamatan Pancoran Mas, Depok</li>\\n<li>Kecamatan Kramat Jati, Jakarta Timur</li>\\n</ul>\\n\\n<p>Layanan kas keliling ini menyediakan berbagai fasilitas perbankan seperti setoran tunai, penarikan tunai, pembayaran angsuran, dan pembukaan rekening baru. Jadwal kunjungan kas keliling dapat dilihat di website resmi atau menghubungi customer service.</p>\\n\\n<p>\\\"Dengan ekspansi ini, kami berharap dapat melayani lebih banyak masyarakat yang membutuhkan akses layanan perbankan syariah,\\\" kata Direktur Operasional BPR Syariah.</p>\", \"excerpt\": \"BPR Syariah memperluas jangkauan layanan kas keliling ke 5 kecamatan baru untuk memberikan akses yang lebih mudah bagi masyarakat.\", \"category\": \"Berita\", \"author_id\": null, \"created_at\": \"2025-12-31 15:16:18\", \"updated_at\": \"2025-12-31 15:16:18\", \"is_published\": 1, \"published_at\": \"2025-12-16 15:16:18\", \"featured_image\": null}', NULL, '10.10.10.28', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 'http://10.10.10.37:8000/admin/news/3', 'DELETE', '2025-12-31 16:56:38', '2025-12-31 16:56:38');
INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('65', '10', 'Muhammad Fadly', 'delete', 'App\\Models\\News', '4', 'Menghapus Berita: Sosialisasi Literasi Keuangan Syariah di Sekolah-Sekolah', '{\"id\": 4, \"slug\": \"sosialisasi-literasi-keuangan-syariah-di-sekolah-sekolah\", \"title\": \"Sosialisasi Literasi Keuangan Syariah di Sekolah-Sekolah\", \"author\": \"Tim CSR\", \"content\": \"<p>Sebagai bagian dari program Corporate Social Responsibility (CSR), BPR Syariah mengadakan program sosialisasi literasi keuangan syariah di berbagai sekolah menengah atas di wilayah Jabodetabek.</p>\\n\\n<p>Program ini bertujuan untuk meningkatkan pemahaman generasi muda tentang prinsip-prinsip keuangan syariah dan pentingnya mengelola keuangan dengan baik sejak dini.</p>\\n\\n<p>Materi yang disampaikan meliputi:</p>\\n<ul>\\n<li>Pengenalan dasar ekonomi syariah</li>\\n<li>Perbedaan sistem keuangan konvensional dan syariah</li>\\n<li>Tips mengelola keuangan pribadi</li>\\n<li>Pentingnya menabung dan berinvestasi</li>\\n</ul>\\n\\n<p>Hingga saat ini, program telah menjangkau lebih dari 2.000 siswa dari 15 sekolah. Antusiasme siswa sangat tinggi, terlihat dari banyaknya pertanyaan dan diskusi yang muncul selama sesi sosialisasi.</p>\\n\\n<p>Program ini akan terus berlanjut dengan target menjangkau 50 sekolah pada tahun 2025.</p>\", \"excerpt\": \"BPR Syariah mengadakan program sosialisasi literasi keuangan syariah di sekolah-sekolah untuk meningkatkan pemahaman generasi muda.\", \"category\": \"Berita\", \"author_id\": null, \"created_at\": \"2025-12-31 15:16:18\", \"updated_at\": \"2025-12-31 15:16:18\", \"is_published\": 1, \"published_at\": \"2025-12-11 15:16:18\", \"featured_image\": null}', NULL, '10.10.10.28', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 'http://10.10.10.37:8000/admin/news/4', 'DELETE', '2025-12-31 16:56:42', '2025-12-31 16:56:42');
INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('66', '10', 'Muhammad Fadly', 'delete', 'App\\Models\\News', '5', 'Menghapus Berita: Kerjasama Strategis dengan Koperasi Syariah Nasional', '{\"id\": 5, \"slug\": \"kerjasama-strategis-dengan-koperasi-syariah-nasional\", \"title\": \"Kerjasama Strategis dengan Koperasi Syariah Nasional\", \"author\": \"Divisi Kemitraan\", \"content\": \"<p>BPR Syariah menandatangani nota kesepahaman (MoU) dengan Koperasi Syariah Nasional untuk mengembangkan ekosistem keuangan syariah yang lebih kuat dan terintegrasi.</p>\\n\\n<p>Kerjasama ini mencakup beberapa area strategis:</p>\\n<ul>\\n<li>Pengembangan produk keuangan syariah bersama</li>\\n<li>Pelatihan dan pengembangan SDM</li>\\n<li>Sharing knowledge dan best practices</li>\\n<li>Program edukasi masyarakat tentang keuangan syariah</li>\\n</ul>\\n\\n<p>Melalui kerjasama ini, diharapkan dapat tercipta sinergi yang saling menguntungkan dan memberikan manfaat yang lebih besar bagi masyarakat, khususnya dalam mengakses layanan keuangan syariah.</p>\\n\\n<p>\\\"Kerjasama ini sejalan dengan visi kami untuk menjadi bagian dari ekosistem keuangan syariah yang kuat di Indonesia,\\\" ungkap Direktur Utama BPR Syariah saat penandatanganan MoU.</p>\", \"excerpt\": \"BPR Syariah menjalin kerjasama strategis dengan Koperasi Syariah Nasional untuk memperkuat ekosistem keuangan syariah.\", \"category\": \"Berita\", \"author_id\": null, \"created_at\": \"2025-12-31 15:16:18\", \"updated_at\": \"2025-12-31 15:16:18\", \"is_published\": 1, \"published_at\": \"2025-12-06 15:16:18\", \"featured_image\": null}', NULL, '10.10.10.28', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 'http://10.10.10.37:8000/admin/news/5', 'DELETE', '2025-12-31 16:56:46', '2025-12-31 16:56:46');
