INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('103', '4', 'Super Admin', 'update', 'App\\Models\\Auction', '1', 'Mengubah Lelang: Lelang Rumah Tinggal 2 Lantai di Perumahan Griya Asri A', '{\"slug\": \"lelang-rumah-tinggal-2-lantai-di-perumahan-griya-asri\", \"title\": \"Lelang Rumah Tinggal 2 Lantai di Perumahan Griya Asri\", \"description\": \"Rumah tinggal 2 lantai dalam kondisi baik dan terawat. Lokasi strategis di perumahan elit dengan keamanan 24 jam.\\n\\nSpesifikasi:\\n- 4 Kamar Tidur\\n- 3 Kamar Mandi\\n- Ruang Tamu & Keluarga\\n- Dapur + Pantry\\n- Carport 2 Mobil\\n- Taman Depan & Belakang\\n- Listrik 2200 Watt\\n- Air PDAM\\n- Internet Ready\\n\\nFasilitas Perumahan:\\n- Keamanan 24 Jam\\n- Taman Bermain Anak\\n- Jogging Track\\n- Dekat Sekolah & Mall\", \"terms_conditions\": \"1. Peserta lelang wajib menyetorkan uang jaminan paling lambat 1 hari sebelum pelaksanaan lelang.\\n2. Uang jaminan yang tidak menang akan dikembalikan paling lambat 3 hari kerja setelah lelang.\\n3. Pemenang lelang wajib melunasi sisa pembayaran dalam waktu 5 hari kerja.\\n4. Biaya-biaya yang menjadi tanggungan pembeli: BPHTB, biaya balik nama, dan biaya lelang 2.5%.\\n5. Objek lelang dijual dalam kondisi apa adanya (as is).\\n6. Pengosongan objek lelang menjadi tanggung jawab pemenang lelang.\", \"viewing_schedule\": \"Jadwal Open House:\\n- Sabtu, 07 January 2026 pukul 09:00 - 12:00 WIB\\n- Minggu, 08 January 2026 pukul 09:00 - 12:00 WIB\\n\\nHubungi contact person untuk konfirmasi kehadiran.\"}', '{\"slug\": \"lelang-rumah-tinggal-2-lantai-di-perumahan-griya-asri-a\", \"title\": \"Lelang Rumah Tinggal 2 Lantai di Perumahan Griya Asri A\", \"description\": \"Rumah tinggal 2 lantai dalam kondisi baik dan terawat. Lokasi strategis di perumahan elit dengan keamanan 24 jam. Spesifikasi:\\r\\n- 4 Kamar Tidur\\r\\n- 3 Kamar Mandi\\r\\n- Ruang Tamu & Keluarga\\r\\n- Dapur + Pantry\\r\\n- Carport 2 Mobil\\r\\n- Taman Depan & Belakang\\r\\n- Listrik 2200 Watt\\r\\n- Air PDAM\\r\\n- Internet Ready Fasilitas Perumahan:\\r\\n- Keamanan 24 Jam\\r\\n- Taman Bermain Anak\\r\\n- Jogging Track\\r\\n- Dekat Sekolah & Mall\", \"terms_conditions\": \"1. Peserta lelang wajib menyetorkan uang jaminan paling lambat 1 hari sebelum pelaksanaan lelang.\\r\\n2. Uang jaminan yang tidak menang akan dikembalikan paling lambat 3 hari kerja setelah lelang.\\r\\n3. Pemenang lelang wajib melunasi sisa pembayaran dalam waktu 5 hari kerja.\\r\\n4. Biaya-biaya yang menjadi tanggungan pembeli: BPHTB, biaya balik nama, dan biaya lelang 2.5%.\\r\\n5. Objek lelang dijual dalam kondisi apa adanya (as is).\\r\\n6. Pengosongan objek lelang menjadi tanggung jawab pemenang lelang.\", \"viewing_schedule\": \"Jadwal Open House:\\r\\n- Sabtu, 07 January 2026 pukul 09:00 - 12:00 WIB\\r\\n- Minggu, 08 January 2026 pukul 09:00 - 12:00 WIB Hubungi contact person untuk konfirmasi kehadiran.\"}', '10.10.10.37', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36 Edg/144.0.0.0', 'http://10.10.10.37:8000/admin/auctions/1', 'PUT', '2025-12-31 20:49:02', '2025-12-31 20:49:02');
