INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('143', '12', 'Yulianto', 'create', 'App\\Models\\Product', '12', 'Membuat Produk: Pembiayaan Kendaraan Bermotor', NULL, '{\"id\": 12, \"name\": \"Pembiayaan Kendaraan Bermotor\", \"slug\": \"pembiayaan-kendaraan-bermotor\", \"type\": \"pembiayaan_syariah\", \"image\": null, \"benefits\": \"[\\\"Bebas Riba\\\",\\\"Hubungan bank dan nasabah adalah Penjual dan Pembeli, bukan Kreditur dan Debitur.\\\",\\\"Margin Kompetitif\\\",\\\"Karena ini adalah akad jual beli, angsuran per bulan tidak akan berubah meskipun suku bunga pasar naik. Ini memberikan ketenangan bagi perencanaan keuangan nasabah.\\\"]\", \"features\": \"[]\", \"image_alt\": null, \"is_active\": true, \"created_at\": \"2026-01-02 15:50:38\", \"updated_at\": \"2026-01-02 15:50:38\", \"description\": \"merupakan transaksi jual beli antara bank (sebagai penjual) dan nasabah (sebagai pembeli), di mana bank membeli kendaraan yang diinginkan nasabah dan menjualnya kembali kepada nasabah dengan harga yang telah ditambah margin keuntungan.\\r\\n\\r\\nDalam sistem syariah, bank tidak meminjamkan uang untuk membeli motor/mobil, melainkan bank \\\"menyediakan barangnya\\\" untuk Anda.\", \"requirements\": \"[\\\"Warga Negara Indonesia Usia Minimal 21 Tahun\\\",\\\"Memiliki sumber penghasilan untuk pengembalian pembiayaan\\\",\\\"Fokotopi KTP Pemohon\\\",\\\"Fokotopi KTP Pasangan\\\",\\\"Fotokopi Kartu Keluarga\\\",\\\"Fotokopi Akte Nikah\\\\/Cerai\\\",\\\"Slip Gaji 1 Bulan Terakhir atau Surat Keterangan Penghasilan\\\",\\\"Fotokopi KTP seluruh pengurus aktif\\\",\\\"Fotokopi Akta pendirian dan perubahan perusahaan\\\",\\\"Fotokopi SK Kemenkumham Fotokopi NIB (Nomor Induk Berusaha)\\\",\\\"Fotokopi NPWP Perusahaan\\\",\\\"Fotokopi Surat Keterangan Domisili Perusahaan (apabila alamat perusahaan tidak sesuai dengan NIB)\\\"]\", \"interest_rate\": \"Margin 15%\", \"order_position\": \"0\", \"short_description\": \"Pembiayaan Kendaraan Bermotor Merupakan Pembiayaan yang menggunakan Akad Murabahah saat bertransaksi\"}', '10.10.10.37', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36 Edg/144.0.0.0', 'http://10.10.10.37:8000/admin/products', 'POST', '2026-01-02 15:50:38', '2026-01-02 15:50:38');
