INSERT INTO `audit_trails` (`id`, `user_id`, `user_name`, `action`, `model_type`, `model_id`, `description`, `old_values`, `new_values`, `ip_address`, `user_agent`, `url`, `method`, `created_at`, `updated_at`) VALUES ('146', '12', 'Yulianto', 'create', 'App\\Models\\Product', '13', 'Membuat Produk: Pembiayaan Sertifikasi Guru (CikGU)', NULL, '{\"id\": 13, \"name\": \"Pembiayaan Sertifikasi Guru (CikGU)\", \"slug\": \"pembiayaan-sertifikasi-guru-cikgu\", \"type\": \"pembiayaan_syariah\", \"image\": null, \"benefits\": \"[\\\"Tanpa Jaminan Tambahan (Opsional): Seringkali sertifikat pendidik atau SK pengangkatan dan kartu ATM tunjangan dijadikan jaminan utama tanpa perlu agunan fisik seperti sertifikat tanah.\\\",\\\"Angsuran Menyesuaikan: Jadwal pembayaran cicilan biasanya bisa disesuaikan dengan jadwal cairnya dana sertifikasi (sistem ballon payment atau potongan saat cair).\\\",\\\"Jadwal pembayaran cicilan biasanya bisa disesuaikan dengan jadwal cairnya dana sertifikasi\\\",\\\"Proses Cepat: Karena bank sudah bekerja sama dengan dinas terkait, proses verifikasi data guru biasanya lebih mudah dan cepat.\\\",\\\"Sesuai Syariah: Tidak menggunakan sistem bunga, melainkan margin keuntungan atau fee jasa yang disepakati di awal.\\\"]\", \"features\": \"[\\\"Jika dana digunakan untuk membeli barang (seperti motor, laptop, atau material bangunan) maka menggunakan akad murabahah.\\\",\\\"Jika dana digunakan untuk membayar jasa (seperti biaya pendidikan anak, biaya umroh, atau pengobatan) maka menggunakan akad Ijarah multijasa.\\\"]\", \"image_alt\": null, \"is_active\": true, \"created_at\": \"2026-01-02 15:59:59\", \"updated_at\": \"2026-01-02 15:59:59\", \"description\": \"produk pembiayaan yang dikhususkan bagi guru atau tenaga pendidik yang telah memiliki Sertifikat Pendidik dan menerima Tunjangan Profesi Guru (TPG).\", \"requirements\": \"[\\\"Fotokopi KTP, KK, dan Buku Nikah.\\\",\\\"Asli Sertifikat Pendidik.\\\",\\\"Asli SK Pegawai (PNS atau Yayasan).\\\",\\\"Print out rekening koran\\\\/buku tabungan tempat masuknya dana sertifikasi.\\\",\\\"Surat Rekomendasi dari Kepala Sekolah atau Dinas Pendidikan.\\\"]\", \"interest_rate\": null, \"order_position\": \"1\", \"short_description\": \"produk pembiayaan yang dikhususkan bagi guru atau tenaga pendidik yang telah memiliki Sertifikat Pendidik dan menerima Tunjangan Profesi Guru (TPG).\"}', '10.10.10.37', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36 Edg/144.0.0.0', 'http://10.10.10.37:8000/admin/products', 'POST', '2026-01-02 15:59:59', '2026-01-02 15:59:59');
