INSERT INTO `board_members` (`id`, `name`, `slug`, `position`, `type`, `photo`, `biography`, `education`, `experience`, `order_position`, `created_at`, `updated_at`) VALUES ('1', 'Drs. Sugianto, M.Si.', 'drs-sugianto-msi', 'Komisaris', 'komisaris', 'board-members/qBFFPylO2J4zcPaTuggE8TlKyQL0FNCYiRqq4w4t.png', 'Drs. Sugianto, M.Si., merupakan pria kelahiran Lampur, 11 September 1964. Mengawali karir profesionalnya sebagai Guru selama periode 1989-2006. Selain itu pernah menjabat sebagai Kepala Dinas Pendidikan Kabupaten Bangka Tengah hingga menjadi Sekretaris Daerah Kabupaten Bangka Tengah. Sejak tahun 2018 hingga saat ini, beliau masih dipercaya menjabat sebagai Komisaris PT. BPRS Bangka Belitung.', '[\"S2 - Magister Sains\", \"S1 - Sarjana Pendidikan\"]', '[\"Komisaris PT. BPRS Bangka Belitung (2018 - sekarang)\", \"Sekretaris Daerah Kabupaten Bangka Tengah\", \"Kepala Dinas Pendidikan Kabupaten Bangka Tengah\", \"Guru (1989 - 2006)\"]', '1', '2025-12-31 15:16:18', '2025-12-31 17:48:39');
INSERT INTO `board_members` (`id`, `name`, `slug`, `position`, `type`, `photo`, `biography`, `education`, `experience`, `order_position`, `created_at`, `updated_at`) VALUES ('2', 'Chairul Ichwan, S.E., CIRBD', 'chairul-ichwan-se-cirbd', 'Direktur Utama', 'direksi', 'board-members/ZOMugWXNF9rnPGAOLlbm2wvpNKxLnQpjSQjnUqr3.png', 'Pria kelahiran Pangkalpinang, 10 Juni 1982 merupakan seorang putra terbaik daerah Provinsi Kepulauan Bangka Belitung yang mengenyam pendidikan formal di SD Muhammadiyah Pangkalpinang, SMP Muhammadiyah Pangkalpinang, SMA Muhammadiyah Pangkalpinang dan merupakan alumni Fakultas Ekonomi & Bisnis/Akuntansi Universitas Pendidikan Indonesia Bandung tahun 2007. Selama berkarir di dunia kerja pernah bergabung di PT Bank Muamalat Indonesia (2007-2016) dengan jabatan terakhir Head of Financing Kantor Cabang Utama Pangkalpinang. Selanjutnya pada 2017-2018 bergabung di PT. BPRS Bangka Belitung sebagai Kasubdiv Funding & Lending serta pernah menjabat sebagai Kasubdiv Remedial & AYDA. Pada periode 2018-2019 diberikan kepercayaan menjadi Direktur di PT. BPR Kapital Mandiri. Selanjutnya pada tahun 2020 hingga saat ini masih dipercaya menjadi Direktur Utama di PT. BPRS Bangka Belitung.', '[\"S1 Akuntansi - Fakultas Ekonomi & Bisnis, Universitas Pendidikan Indonesia Bandung (2007)\", \"SMA Muhammadiyah Pangkalpinang\", \"SMP Muhammadiyah Pangkalpinang\", \"SD Muhammadiyah Pangkalpinang\"]', '[\"Direktur Utama PT. BPRS Bangka Belitung (2020 - sekarang)\", \"Direktur PT. BPR Kapital Mandiri (2018 - 2019)\", \"Kasubdiv Remedial & AYDA PT. BPRS Bangka Belitung\", \"Kasubdiv Funding & Lending PT. BPRS Bangka Belitung (2017 - 2018)\", \"Head of Financing KC Utama Pangkalpinang, PT Bank Muamalat Indonesia (2007 - 2016)\"]', '1', '2025-12-31 15:16:18', '2025-12-31 17:49:10');
INSERT INTO `board_members` (`id`, `name`, `slug`, `position`, `type`, `photo`, `biography`, `education`, `experience`, `order_position`, `created_at`, `updated_at`) VALUES ('3', 'Hendra Dharma, S.E.', 'hendra-dharma-se', 'Direktur Marketing & Bisnis', 'direksi', 'board-members/MYCLFfVOMau6wthqIHLp8pnMyo6ZI0ITTt4Kl84a.png', 'Pria kelahiran Pangkalpinang, 30 April 1980. Merupakan seorang putra daerah Provinsi Kepulauan Bangka Belitung. Mulai bergabung di PT. BPRS Bangka Belitung sejak tahun 2006 hingga saat ini beliau masih dipercaya menjabat sebagai Direktur di PT. BPRS Bangka Belitung.', '[\"S1 Ekonomi\"]', '[\"Direktur Marketing & Bisnis PT. BPRS Bangka Belitung (sekarang)\", \"Bergabung di PT. BPRS Bangka Belitung sejak 2006\"]', '2', '2025-12-31 15:16:18', '2025-12-31 17:49:28');
INSERT INTO `board_members` (`id`, `name`, `slug`, `position`, `type`, `photo`, `biography`, `education`, `experience`, `order_position`, `created_at`, `updated_at`) VALUES ('4', 'H. Syaipul Zohri', 'h-syaipul-zohri', 'Ketua Dewan Pengawas Syariah', 'pengawas_syariah', 'board-members/UTUjTpJgF9dOhslTYfdN5b1GkXI6D3FK8MVnalmI.png', 'Dewan Pengawas Syariah PT. BPRS Bangka Belitung sejak 2009. Tercatat sebagai PNS Kementerian Agama dan aktif di berbagai organisasi Islam serta pernah menjabat sebagai Ketua BAZNAS Kabupaten Bangka. Beliau juga memimpin MUI Kabupaten Bangka.', '[\"Pendidikan Agama Islam\"]', '[\"Dewan Pengawas Syariah PT. BPRS Bangka Belitung (2009 - sekarang)\", \"Ketua MUI Kabupaten Bangka\", \"Ketua BAZNAS Kabupaten Bangka\", \"PNS Kementerian Agama\"]', '1', '2025-12-31 15:16:18', '2025-12-31 17:50:02');
INSERT INTO `board_members` (`id`, `name`, `slug`, `position`, `type`, `photo`, `biography`, `education`, `experience`, `order_position`, `created_at`, `updated_at`) VALUES ('5', 'H. Hasyim Syachroni', 'h-hasyim-syachroni', 'Anggota Dewan Pengawas Syariah', 'pengawas_syariah', 'board-members/ZCxm48UeDDYr9p6KeSZIQc8yBQWpKZUTkTJygPQI.png', 'Dewan Pengawas Syariah PT. BPRS Bangka Belitung sejak 2009. Tercatat sebagai Ketua MUI dan BAZNAS Kabupaten Bangka Tengah.', '[\"Pendidikan Agama Islam\"]', '[\"Dewan Pengawas Syariah PT. BPRS Bangka Belitung (2009 - sekarang)\", \"Ketua MUI Kabupaten Bangka Tengah\", \"Ketua BAZNAS Kabupaten Bangka Tengah\"]', '2', '2025-12-31 15:16:18', '2025-12-31 17:50:12');
