INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES ('bank-syariah-babel-cache-company_info', 'O:22:\"App\\Models\\CompanyInfo\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:13:\"company_infos\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:42:{s:2:\"id\";i:1;s:4:\"name\";s:52:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung\";s:7:\"tagline\";s:54:\"Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai\";s:4:\"logo\";s:52:\"company/ipgCgHRw7og6Gb2bSphQUBLjTNP1p82l6nuRtL9d.png\";s:7:\"favicon\";s:52:\"company/aV346Y9QEvdbeJ88iwZPZx3G3lKGBuSSwFqApK6v.ico\";s:7:\"address\";s:91:\"TJ TOWER, Jl. Kampung Melayu, Bukit Merapin 33172, Pangkalpinang, Kepulauan Bangka Belitung\";s:5:\"phone\";s:12:\"0717-9103567\";s:3:\"fax\";N;s:8:\"whatsapp\";s:12:\"0717-9103567\";s:5:\"email\";s:25:\"customercare@bprsbabel.id\";s:13:\"email_contact\";s:28:\"bprsbangkabelitung@gmail.com\";s:15:\"email_complaint\";N;s:20:\"email_whistleblowing\";N;s:7:\"website\";s:20:\"https://bprsbabel.id\";s:11:\"description\";s:320:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung (BPRS Babel) adalah bank syariah daerah yang melayani masyarakat Provinsi Kepulauan Bangka Belitung dengan prinsip syariah. Bank ini berkomitmen untuk menggerakkan pemberdayaan ekonomi rakyat dan menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha.\";s:6:\"vision\";s:108:\"Terwujudnya Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai yang Terpercaya, Sehat dan Menguntungkan.\";s:7:\"mission\";s:450:\"1. Menggerakkan pemberdayaan ekonomi rakyat dalam rangka turut serta berperan menuju masyarakat Provinsi Kepulauan Bangka Belitung yang maju, mandiri dan sejahtera. 2. Menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha. 3. Meningkatkan kualitas pelayanan di seluruh kantor. 4. Meningkatkan kuantitas dan kualitas sumber daya insani menuju tenaga kerja yang profesional. 5. Meningkatkan kerja sama dan bersinergi dengan pihak lain.\";s:7:\"history\";s:464:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung (BPRS Babel) merupakan bank syariah daerah yang beroperasi di wilayah Provinsi Kepulauan Bangka Belitung. Bank ini didirikan untuk melayani kebutuhan perbankan syariah masyarakat dengan berbagai produk simpanan syariah, deposito syariah, dan pembiayaan syariah. BPRS Babel terus berkembang dengan membuka kantor cabang dan kantor kas di berbagai wilayah Bangka Belitung untuk menjangkau lebih banyak masyarakat.\";s:22:\"organization_structure\";s:52:\"company/ikbN5CBGv8LdSBIbYVZDngfDfT60tcbsz5xXzYst.jpg\";s:16:\"established_year\";i:2002;s:21:\"stat_years_experience\";i:23;s:19:\"stat_branch_offices\";i:7;s:17:\"stat_total_assets\";N;s:17:\"stat_cash_offices\";i:5;s:24:\"stat_mobile_cash_offices\";i:1;s:20:\"legacy_visitor_count\";i:0;s:10:\"created_at\";s:19:\"2025-12-31 15:16:18\";s:10:\"updated_at\";s:19:\"2025-12-31 18:32:28\";s:8:\"facebook\";s:55:\"https://www.facebook.com/profile.php?id=100074965290543\";s:9:\"instagram\";s:67:\"https://www.instagram.com/bprsbangkabelitung/?igshid=YmMyMTA2M2Y%3D\";s:7:\"twitter\";N;s:7:\"youtube\";s:56:\"https://www.youtube.com/channel/UCD_8LaoGl-1AISl6X93WR1g\";s:8:\"linkedin\";N;s:6:\"tiktok\";N;s:11:\"ojk_license\";s:30:\"Terdaftar dan diawasi oleh OJK\";s:11:\"ojk_tagline\";s:49:\"Terdaftar dan diawasi oleh Otoritas Jasa Keuangan\";s:11:\"lps_tagline\";s:121:\"Bank merupakan peserta penjaminan LPS | Maksimum nilai simpanan yang dijamin LPS per Nasabah per Bank adalah Rp. 2 Miliar\";s:20:\"lps_guarantee_amount\";s:16:\"Rp 2.000.000.000\";s:18:\"footer_description\";s:124:\"Melayani dengan prinsip syariah untuk kesejahteraan masyarakat Negeri Serumpun Sebalai. Terpercaya, amanah, dan profesional.\";s:16:\"meta_description\";s:181:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung - Bank syariah terpercaya di Kepulauan Bangka Belitung dengan produk simpanan syariah, deposito syariah, dan pembiayaan syariah.\";s:13:\"meta_keywords\";s:138:\"BPRS Babel, Bank Syariah Bangka Belitung, Simpanan Syariah, Pembiayaan Syariah, Deposito Syariah, Bank Bangka Belitung, Bank Syariah Babel\";s:17:\"operational_hours\";s:75:\"{\"Sabtu\": \"Tutup\", \"Minggu\": \"Tutup\", \"Senin - Jumat\": \"08:00 - 16:00 WIB\"}\";}s:11:\"\0*\0original\";a:42:{s:2:\"id\";i:1;s:4:\"name\";s:52:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung\";s:7:\"tagline\";s:54:\"Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai\";s:4:\"logo\";s:52:\"company/ipgCgHRw7og6Gb2bSphQUBLjTNP1p82l6nuRtL9d.png\";s:7:\"favicon\";s:52:\"company/aV346Y9QEvdbeJ88iwZPZx3G3lKGBuSSwFqApK6v.ico\";s:7:\"address\";s:91:\"TJ TOWER, Jl. Kampung Melayu, Bukit Merapin 33172, Pangkalpinang, Kepulauan Bangka Belitung\";s:5:\"phone\";s:12:\"0717-9103567\";s:3:\"fax\";N;s:8:\"whatsapp\";s:12:\"0717-9103567\";s:5:\"email\";s:25:\"customercare@bprsbabel.id\";s:13:\"email_contact\";s:28:\"bprsbangkabelitung@gmail.com\";s:15:\"email_complaint\";N;s:20:\"email_whistleblowing\";N;s:7:\"website\";s:20:\"https://bprsbabel.id\";s:11:\"description\";s:320:\"PT. Bank Perekonomian Rakyat Syariah Bangka Belitung (BPRS Babel) adalah bank syariah daerah yang melayani masyarakat Provinsi Kepulauan Bangka Belitung dengan prinsip syariah. Bank ini berkomitmen untuk menggerakkan pemberdayaan ekonomi rakyat dan menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha.\";s:6:\"vision\";s:108:\"Terwujudnya Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai yang Terpercaya, Sehat dan Menguntungkan.\";s:7:\"mission\";s:450:\"1. Menggerakkan pemberdayaan ekonomi rakyat dalam rangka turut serta berperan menuju masyarakat Provinsi Kepulauan Bangka Belitung yang maju, mandiri dan sejahtera. 2. Menyebarluaskan nilai-nilai 