INSERT INTO `company_infos` (`id`, `name`, `tagline`, `logo`, `favicon`, `address`, `phone`, `fax`, `whatsapp`, `email`, `email_contact`, `email_complaint`, `email_whistleblowing`, `website`, `description`, `vision`, `mission`, `history`, `organization_structure`, `established_year`, `stat_years_experience`, `stat_branch_offices`, `stat_total_assets`, `stat_cash_offices`, `stat_mobile_cash_offices`, `legacy_visitor_count`, `created_at`, `updated_at`, `facebook`, `instagram`, `twitter`, `youtube`, `linkedin`, `tiktok`, `ojk_license`, `ojk_tagline`, `lps_tagline`, `lps_guarantee_amount`, `footer_description`, `meta_description`, `meta_keywords`, `operational_hours`) VALUES ('1', 'PT. Bank Perekonomian Rakyat Syariah Bangka Belitung', 'Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai', 'company/ipgCgHRw7og6Gb2bSphQUBLjTNP1p82l6nuRtL9d.png', 'company/aV346Y9QEvdbeJ88iwZPZx3G3lKGBuSSwFqApK6v.ico', 'TJ TOWER, Jl. Kampung Melayu, Bukit Merapin 33172, Pangkalpinang, Kepulauan Bangka Belitung', '0717-9103567', NULL, '0717-9103567', 'customercare@bprsbabel.id', 'bprsbangkabelitung@gmail.com', NULL, NULL, 'https://bprsbabel.id', 'PT. Bank Perekonomian Rakyat Syariah Bangka Belitung (BPRS Babel) adalah bank syariah daerah yang melayani masyarakat Provinsi Kepulauan Bangka Belitung dengan prinsip syariah. Bank ini berkomitmen untuk menggerakkan pemberdayaan ekonomi rakyat dan menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha.', 'Terwujudnya Bank Daerah Dambaan Masyarakat Negeri Serumpun Sebalai yang Terpercaya, Sehat dan Menguntungkan.', '1. Menggerakkan pemberdayaan ekonomi rakyat dalam rangka turut serta berperan menuju masyarakat Provinsi Kepulauan Bangka Belitung yang maju, mandiri dan sejahtera. 2. Menyebarluaskan nilai-nilai Islam dalam bidang ekonomi dan dunia usaha. 3. Meningkatkan kualitas pelayanan di seluruh kantor. 4. Meningkatkan kuantitas dan kualitas sumber daya insani menuju tenaga kerja yang profesional. 5. Meningkatkan kerja sama dan bersinergi dengan pihak lain.', 'PT. Bank Perekonomian Rakyat Syariah Bangka Belitung (BPRS Babel) merupakan bank syariah daerah yang beroperasi di wilayah Provinsi Kepulauan Bangka Belitung. Bank ini didirikan untuk melayani kebutuhan perbankan syariah masyarakat dengan berbagai produk simpanan syariah, deposito syariah, dan pembiayaan syariah. BPRS Babel terus berkembang dengan membuka kantor cabang dan kantor kas di berbagai wilayah Bangka Belitung untuk menjangkau lebih banyak masyarakat.', 'company/ikbN5CBGv8LdSBIbYVZDngfDfT60tcbsz5xXzYst.jpg', '2002', '23', '7', NULL, '5', '1', '0', '2025-12-31 15:16:18', '2025-12-31 18:32:28', 'https://www.facebook.com/profile.php?id=100074965290543', 'https://www.instagram.com/bprsbangkabelitung/?igshid=YmMyMTA2M2Y%3D', NULL, 'https://www.youtube.com/channel/UCD_8LaoGl-1AISl6X93WR1g', NULL, NULL, 'Terdaftar dan diawasi oleh OJK', 'Terdaftar dan diawasi oleh Otoritas Jasa Keuangan', 'Bank merupakan peserta penjaminan LPS | Maksimum nilai simpanan yang dijamin LPS per Nasabah per Bank adalah Rp. 2 Miliar', 'Rp 2.000.000.000', 'Melayani dengan prinsip syariah untuk kesejahteraan masyarakat Negeri Serumpun Sebalai. Terpercaya, amanah, dan profesional.', 'PT. Bank Perekonomian Rakyat Syariah Bangka Belitung - Bank syariah terpercaya di Kepulauan Bangka Belitung dengan produk simpanan syariah, deposito syariah, dan pembiayaan syariah.', 'BPRS Babel, Bank Syariah Bangka Belitung, Simpanan Syariah, Pembiayaan Syariah, Deposito Syariah, Bank Bangka Belitung, Bank Syariah Babel', '{\"Sabtu\": \"Tutup\", \"Minggu\": \"Tutup\", \"Senin - Jumat\": \"08:00 - 16:00 WIB\"}');
