INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('5', 'Tabungan Hidayah', 'tabungan-hidayah', 'simpanan_syariah', 'Merupakan Produk Simpanan Syariah yang menggunakan Akad Mudharabah, nasabah akan mendapatkan bagi hasil sesuai dengan nisbah (porsi) yang disepakati di awal.', 'Tabungan hidayah Merupakan Produk Simpanan Syariah yang menggunakan Akad Mudharabah, nasabah akan mendapatkan bagi hasil sesuai dengan nisbah (porsi) yang disepakati di awal.', 'Nisbah 20%', '[\"Setoran awal minimal Rp 50.000\", \"Dapat ditarik kapan saja\", \"Mendapat bonus sesuai kebijakan bank\"]', '[\"KTP yang masih berlaku\", \"NPWP (untuk setoran di atas Rp 20 juta)\", \"Setoran awal minimal Rp 50.000\", \"Mengisi formulir pembukaan rekening\"]', '[\"Aman dan terpercaya\", \"Sesuai prinsip syariah\", \"Mudah diakses\", \"Bonus yang kompetitif\"]', 'products/LeEU3LXZXFAij1hQHxeAeDSy2ogNbchYyBzyJsAh.jpg', NULL, '1', '1', '2025-12-31 15:16:18', '2026-01-02 15:41:55');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('9', 'Tabungan Simpanan Pelajar', 'tabungan-simpanan-pelajar', 'simpanan_syariah', 'Menabung Sejak Dini, Melatih Disiplin Diri', 'aku pelajar, aku generasi simpel', NULL, '[]', '[\"Foto Copy Kartu Keluarga\", \"Foto Copy KTP Orang Tua atau Wali\", \"Foto Copy Kartu Pelajar atau surat keterangan dari sekolah\", \"KIA (Kartu Identitas anak)\", \"Setoran awal Rp.5000\"]', '[\"Dikelola sesuai Syariah\", \"Bagi Hasil Kompetitif\", \"Aman dI awasi OJK serta dijamin LPS\", \"Setoran selanjutnya minimal Rp.1000\"]', 'products/doC2gXMcS6K54vWhbgDYIWDwIX2UNCpyk8wDyYlv.jpg', NULL, '1', '0', '2026-01-02 09:52:22', '2026-01-02 16:05:09');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('10', 'Deposito Mudharabah', 'deposito-mudharabah', 'deposito_syariah', NULL, 'Deposito Mudharabah BPRS Bangka Belitung adalah produk investasi berjangka dari Bank Pembiayaan Rakyat Syariah (BPRS) Bangka Belitung yang dikelola menggunakan prinsip bagi hasil (Mudharabah Mutlaqah). Dalam produk ini, Anda mempercayakan dana kepada bank untuk dikelola dalam sektor usaha produktif yang halal, dan keuntungannya dibagi sesuai kesepakatan (nisbah).', NULL, '[\"Jangka waktu 1, 3, 6, 12 bulan\", \"Bagi hasil kompetitif\", \"Dapat diperpanjang otomatis\", \"Dapat dijadikan jaminan pembiayaan\"]', '[\"KTP yang masih berlaku\", \"NPWP\", \"Setoran minimal Rp 5.000.000,-\", \"Mengisi formulir pembukaan deposito\", \"KTP Ahli waris\", \"Materai 10.000\"]', '[\"Bagi hasil yang menguntungkan\", \"Investasi yang aman\", \"Sesuai prinsip syariah\", \"Fleksibel dalam jangka waktu\"]', 'products/uC7Cn3fifP3O9ZFHLLOWEFg0vA8MgyMLYQ1jcTh3.jpg', NULL, '1', '0', '2026-01-02 10:23:32', '2026-01-02 16:08:37');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('11', 'Tabungan Wadiah', 'tabungan-wadiah', 'simpanan_syariah', 'Simpanan Wadiah adalah salah satu konsep titipan dalam perbankan syariah di mana nasabah menitipkan dananya kepada bank. Secara bahasa, Wadiah berarti titipan murni dari satu pihak ke pihak lain yang harus dijaga dan dikembalikan kapan saja si penitip menghendakinya.', 'Simpanan Murni / Titipan, Nasabah akan bertindak sebagai penitip yang memberikan amanah kepada bank untuk menyimpan dana tersebut. Nasabah dapat melakukan penarikan dana kapanpun sesuai keinginan nasabah. Tabungan wadiah bebas dari bagi hasil. Bank tidak memberikan bagi hasil kepada nasabah atas dana yang ditempatkan dalam Tabungan Wadiah.', NULL, '[]', '[\"KTP yang masih berlaku\", \"Saldo awal Rp.50.000\"]', '[\"Akad Wadiah yad adh-dhamanah\", \"Dana bersifat titipan\", \"Tanpa Riba\", \"Tidak ada bagi hasil maupun bonus\", \"Aman, terdaftar dan di awasi OJK serta dijamin LPS\"]', 'products/Z8DsSeopqCd5dklAh4Ar1rJh4fmHP9k72DmCHU1T.jpg', 'wadiah', '1', '0', '2026-01-02 13:29:27', '2026-01-02 16:04:11');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('12', 'Pembiayaan Kendaraan Bermotor', 'pembiayaan-kendaraan-bermotor', 'pembiayaan_syariah', 'Pembiayaan Kendaraan Bermotor Merupakan Pembiayaan yang menggunakan Akad Murabahah saat bertransaksi', 'merupakan transaksi jual beli antara bank (sebagai penjual) dan nasabah (sebagai pembeli), di mana bank membeli kendaraan yang diinginkan nasabah dan menjualnya kembali kepada nasabah dengan harga yang telah ditambah margin keuntungan. Dalam sistem syariah, bank tidak meminjamkan uang untuk membeli motor/mobil, melainkan bank \"menyediakan barangnya\" untuk Anda.', 'Margin 16%', '[]', '[\"Warga Negara Indonesia Usia Minimal 21 Tahun\", \"Memiliki sumber penghasilan untuk pengembalian pembiayaan\", \"Fokotopi KTP Pemohon\", \"Fokotopi KTP Pasangan\", \"Fotokopi Kartu Keluarga\", \"Fotokopi Akte Nikah/Cerai\", \"Slip Gaji 1 Bulan Terakhir atau Surat Keterangan Penghasilan\", \"Fotokopi KTP seluruh pengurus aktif\", \"Fotokopi Akta pendirian dan perubahan perusahaan\", \"Fotokopi SK Kemenkumham Fotokopi NIB (Nomor Induk Berusaha)\", \"Fotokopi NPWP Perusahaan\", \"Fotokopi Surat Keterangan Domisili Perusahaan (apabila alamat perusahaan tidak sesuai dengan NIB)\"]', '[\"Bebas Riba\", \"Hubungan bank dan nasabah adalah Penjual dan Pembeli, bukan Kreditur dan Debitur.\", \"Margin Kompetitif\", \"Angsuran per bulan tidak akan berubah meskipun suku bunga pasar naik. Ini memberikan ketenangan bagi perencanaan keuangan nasabah.\", \"Bebas Denda\"]', 'products/1nswfgaC6wSzR6BNFPXnOtV2sDAQYTgVNdxnHeNY.jpg', NULL, '1', '0', '2026-01-02 15:50:38', '2026-01-05 15:31:29');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('13', 'Pembiayaan Sertifikasi Guru (CikGU)', 'pembiayaan-sertifikasi-guru-cikgu', 'pembiayaan_syariah', 'produk pembiayaan yang dikhususkan bagi guru atau tenaga pendidik yang telah memiliki Sertifikat Pendidik dan menerima Tunjangan Profesi Guru (TPG).', 'produk pembiayaan yang dikhususkan bagi guru atau tenaga pendidik yang telah memiliki Sertifikat Pendidik dan menerima Tunjangan Profesi Guru (TPG).', 'Margin 15%', '[\"Jika dana digunakan untuk membeli barang (seperti motor, laptop, atau material bangunan) maka menggunakan akad murabahah.\", \"Jika dana digunakan untuk membayar jasa (seperti biaya pendidikan anak, biaya umroh, atau pengobatan) maka menggunakan akad Ijarah multijasa.\", \"Plafond Max Rp. 100.000.000,-\", \"Jangka waktu 5 tahun dengan usia max 58 tahun\"]', '[\"Fotokopi KTP, KK, dan Buku Nikah.\", \"Asli Sertifikat Pendidik.\", \"Asli SK Pegawai (PNS atau Yayasan).\", \"Print out rekening koran/buku tabungan tempat masuknya dana sertifikasi.\", \"Surat Rekomendasi dari Kepala Sekolah atau Dinas Pendidikan.\"]', '[\"Tanpa Jaminan Tambahan (Opsional): Seringkali sertifikat pendidik atau SK pengangkatan dan kartu ATM tunjangan dijadikan jaminan utama tanpa perlu agunan fisik seperti sertifikat tanah.\", \"Angsuran Menyesuaikan: Jadwal pembayaran cicilan biasanya bisa disesuaikan dengan jadwal cairnya dana sertifikasi (sistem ballon payment atau potongan saat cair).\", \"Jadwal pembayaran cicilan biasanya bisa disesuaikan dengan jadwal cairnya dana sertifikasi\", \"Proses Cepat: Karena bank sudah bekerja sama dengan dinas terkait, proses verifikasi data guru biasanya lebih mudah dan cepat.\", \"Sesuai Syariah: Tidak menggunakan sistem bunga, melainkan margin keuntungan atau fee jasa yang disepakati di awal.\"]', 'products/d8e3fd91-a860-4558-a84d-e924cc6d9882.jpg', NULL, '1', '1', '2026-01-02 15:59:59', '2026-01-05 16:38:19');
INSERT INTO `products` (`id`, `name`, `slug`, `type`, `short_description`, `description`, `interest_rate`, `features`, `requirements`, `benefits`, `image`, `image_alt`, `is_active`, `order_position`, `created_at`, `updated_at`) VALUES ('15', 'Pembiayaan Multigunna', 'pembiayaan-multigunna', 'pembiayaan_syariah', 'Wujudkan Impian Anda untuk Membangun Rumah dan Renovasi Rumah bersama BPRS Bangka Belitung', 'Pembiayaan Multiguna adalah pembiayaan untuk melakukan pembangunan rumah baru atau renovasi bersama BPRS Bangka Belitung', 'Margin 16 %', '[]', '[]', '[\"Proses Cepat\", \"Sesuai prinsip syariah\", \"Insya Allah Berkah\"]', 'products/85zE495IIbcIVVbY9nBF4u8tBhitS8adSTC93ahI.jpg', NULL, '1', '0', '2026-01-02 16:41:10', '2026-01-05 15:31:44');
